// Block (composition) — a horizontally scrollable board of columns and task cards.
// ScrollArea/Stack own arrangement; Card/Badge/Button own Component surfaces, labels, and actions.
import type { Ref } from "react";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "../components/Card";
import { ScrollArea } from "../components/ScrollArea";
import { Stack } from "../layouts/Stack";
import "./KanbanBoard.css";

export interface KanbanBoardProps {
  columns: {
    id: string;
    title: string;
    cards: { id: string; title: string; description?: string; badge?: string }[];
  }[];
  onCardAction?: (cardId: string) => void;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function KanbanBoard({ columns, onCardAction, className, ref }: KanbanBoardProps) {
  return (
    <Stack
      as="section"
      ref={ref}
      aria-label="Kanban board"
      className={className ? `sd-kanbanboard ${className}` : "sd-kanbanboard"}
    >
      {/* The row of columns used to BE the root, with `overflow-x: auto` on it — a scroll region
          with no way to reach it from a keyboard, and one that holds nothing tabbable at all unless
          the consumer passes `onCardAction` (axe scrollable-region-focusable / WCAG 2.1.1). The
          landmark and its label stay on the root; only the scrolling moves. */}
      <ScrollArea orientation="horizontal" className="sd-kanbanboard__scroll">
        <Stack direction="row" gap="medium" align="start" className="sd-kanbanboard__columns">
          {columns.map((column) => (
            <Stack key={column.id} gap="small" className="sd-kanbanboard__column">
              <Stack direction="row" gap="small" align="center" justify="between" className="sd-kanbanboard__column-header">
                <>
                  <h2 className="sd-kanbanboard__title sd-type-title-medium">{column.title}</h2>
                </>
                <Badge aria-label={`${column.cards.length} cards`}>{column.cards.length}</Badge>
              </Stack>
              <Stack gap="small" className="sd-kanbanboard__cards">
                {column.cards.map((card) => (
                  <Card key={card.id}>
                    <CardHeader>
                      <CardTitle>{card.title}</CardTitle>
                      {card.description && <CardDescription>{card.description}</CardDescription>}
                    </CardHeader>
                    {card.badge && (
                      <CardContent>
                        <Badge>{card.badge}</Badge>
                      </CardContent>
                    )}
                    {onCardAction && (
                      <CardFooter>
                        <Button
                          type="button"
                          variant="secondary"
                          size="small"
                          onPress={() => onCardAction(card.id)}
                        >
                          Open
                        </Button>
                      </CardFooter>
                    )}
                  </Card>
            ))}
          </Stack>
        </Stack>
          ))}
        </Stack>
      </ScrollArea>
    </Stack>
  );
}

/* KanbanBoard.css — .sd-kanbanboard (Block)
   Arrangement only. The root is the landmark; the SCROLLPORT is a child (see the tsx). */
.sd-kanbanboard {
  width: 100%;
}

/* The scrollport. `padding-block-end` lives here, not on the root: it reserves the strip the
   horizontal scrollbar occupies, which is only meaningful inside the box that scrolls. ScrollArea
   compensates its gutter padding with an equal negative margin; overriding the padding on this side
   takes the margin with it, so the strip adds below the columns as it always did and the other three
   sides keep the compensated gutter, leaving the columns where they were. */
.sd-kanbanboard__scroll {
  min-width: 0;
  width: 100%;
  padding-block-end: var(--sd-space-small);
  margin-block-end: 0;
}

.sd-kanbanboard__column {
  flex: 0 0 18rem;
}

.sd-kanbanboard__title {
  margin: 0;
}
